-- 창고 1 (WH-001) 시드
-- 원본: warehouse_graph.json
-- 자동창고 노드-엣지 구조 - 확장 입출고 접근형
-- 이 파일은 자동 생성됩니다. 직접 고치지 마세요.
-- 지도를 바꾸려면 JSON 을 고치고 스크립트를 다시 돌리세요.

BEGIN;

-- 기존 기본 지도의 코드 충돌을 피한 뒤 같은 PK에 새 계약을 덮어쓴다.
UPDATE warehouse_edge SET edge_code = '__LARO_MIGRATION_EDGE_' || edge_id WHERE edge_id BETWEEN 10001 AND 10356 AND from_node_id IN (SELECT node_id FROM warehouse_node WHERE warehouse_id = 1);
UPDATE warehouse_node SET node_code = '__LARO_MIGRATION_NODE_' || node_id WHERE warehouse_id = 1 AND node_id BETWEEN 10001 AND 10268;

-- 창고
VALUES (1, '대전 물류센터 A (AI Neo4j)', 13, 7, 1, '대전광역시 유성구', '확장 입출고 접근형 LARO AI Neo4j (220 RouteNode / 354 TRAVERSES)', 'ACTIVE', true, NOW(), NOW())
ON CONFLICT (id) DO UPDATE SET name = excluded.name, width = excluded.width, height = excluded.height, location = excluded.location, description = excluded.description, status = excluded.status, is_shared = excluded.is_shared, updated_at = NOW();

-- 구역 (노드 좌표에서 범위를 계산)
ON CONFLICT (zone_id) DO UPDATE SET warehouse_id = excluded.warehouse_id, name = excluded.name, zone_type = excluded.zone_type, description = excluded.description, min_x = excluded.min_x, max_x = excluded.max_x, min_y = excluded.min_y, max_y = excluded.max_y;

-- 노드 268개
ON CONFLICT (node_id) DO UPDATE SET warehouse_id = excluded.warehouse_id, zone_id = excluded.zone_id, node_code = excluded.node_code, node_type = excluded.node_type, x = excluded.x, y = excluded.y, service_only = excluded.service_only, transit_allowed = excluded.transit_allowed, holding_allowed = excluded.holding_allowed, node_capacity = excluded.node_capacity, resource_type = excluded.resource_type, resource_code = excluded.resource_code, side = excluded.side, route_attributes = excluded.route_attributes;

-- 간선 356개
ON CONFLICT (edge_id) DO UPDATE SET edge_code = excluded.edge_code, from_node_id = excluded.from_node_id, to_node_id = excluded.to_node_id, distance = excluded.distance, direction_type = excluded.direction_type, edge_type = excluded.edge_type, speed_limit_mps = excluded.speed_limit_mps, nominal_travel_time_ms = excluded.nominal_travel_time_ms, cost = excluded.cost, physical_resource_code = excluded.physical_resource_code, service_only = excluded.service_only, mobile_robot_traversable = excluded.mobile_robot_traversable, route_attributes = excluded.route_attributes;

-- 일반 AMR 주행로는 양방향으로 사용한다. 이미 IN/OUT 또는 RETURN_* 두 행으로
-- 왕복을 명시한 경로는 그대로 두어 Neo4j에 중복 역방향 관계가 생기지 않게 한다.
-- 랙/입출고 설비의 service_only 인계 경로는 작업 순서를 표현하므로 변경하지 않는다.
UPDATE warehouse_edge AS edge
SET direction_type = 'BOTH'
WHERE edge.direction_type <> 'BOTH'
  AND edge.mobile_robot_traversable = true
  AND edge.service_only = false
  AND edge.from_node_id IN (
      SELECT node_id
      FROM warehouse_node
      WHERE warehouse_id = 1
  )
  AND NOT EXISTS (
      SELECT 1
      FROM warehouse_edge AS reverse_edge
      WHERE reverse_edge.from_node_id = edge.to_node_id
        AND reverse_edge.to_node_id = edge.from_node_id
        AND reverse_edge.mobile_robot_traversable = true
        AND reverse_edge.service_only = false
  );

-- 충전소 10개
ON CONFLICT (charging_station_id) DO UPDATE SET warehouse_id = excluded.warehouse_id, node_id = excluded.node_id, name = excluded.name;

-- 보관위치 48개 (랙 노드마다 하나)
ON CONFLICT (storage_location_id) DO UPDATE SET warehouse_id = excluded.warehouse_id, node_id = excluded.node_id;

-- 기존 재고 행의 node_id도 보존된 보관위치가 가리키는 새 랙으로 맞춘다.
UPDATE warehouse_items AS wi SET node_id = sl.node_id FROM storage_location AS sl WHERE wi.storage_location_id = sl.storage_location_id AND wi.warehouse_id = 1 AND sl.warehouse_id = 1;

-- 로봇 6대 (충전 슬롯에서 시작)
ON CONFLICT (robot_id) DO UPDATE SET robot_spec_id = excluded.robot_spec_id, warehouse_id = excluded.warehouse_id, node_id = excluded.node_id;

-- 자동 증가 값을 최대 ID 뒤로 옮긴다
SELECT setval(pg_get_serial_sequence('warehouse_node', 'node_id'), GREATEST((SELECT COALESCE(MAX(node_id), 1) FROM warehouse_node), 1), true);
SELECT setval(pg_get_serial_sequence('warehouse_edge', 'edge_id'), GREATEST((SELECT COALESCE(MAX(edge_id), 1) FROM warehouse_edge), 1), true);
SELECT setval(pg_get_serial_sequence('warehouse_zone', 'zone_id'), GREATEST((SELECT COALESCE(MAX(zone_id), 1) FROM warehouse_zone), 1), true);
SELECT setval(pg_get_serial_sequence('charging_station', 'charging_station_id'), GREATEST((SELECT COALESCE(MAX(charging_station_id), 1) FROM charging_station), 1), true);
SELECT setval(pg_get_serial_sequence('storage_location', 'storage_location_id'), GREATEST((SELECT COALESCE(MAX(storage_location_id), 1) FROM storage_location), 1), true);
SELECT setval(pg_get_serial_sequence('robot', 'robot_id'), GREATEST((SELECT COALESCE(MAX(robot_id), 1) FROM robot), 1), true);
SELECT setval(pg_get_serial_sequence('warehouse_layout', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM warehouse_layout), 1), true);

COMMIT;
